201	      masteryGain: clamp(evaluation.masteryGain, 0, 1),
202	      retention: clamp(evaluation.retention, 0, 1),
203	      engagement: clamp(evaluation.engagement, 0, 1),
204	      transfer: clamp(evaluation.transfer, 0, 1),
205	      confusion: clamp(evaluation.confusion, 0, 1),
