327	
328	  const weakest = [...topicBenchmarks].sort((left, right) => left.meanScore - right.meanScore)[0];
329	
330	  const overallScores = topicBenchmarks.map((entry) => entry.meanScore).filter(s => !Number.isNaN(s));
331	  const dataSource = hasLearnerContext
