381	  );
382	  if (result.trace.dataSource === "learner-feedback") {
383	    lines.push(
384	      `- Benchmark uses **learner feedback only** (${result.trace.realOutcomeCount} data points). This is ready for policy evolution.`
385	    );
386	  } else if (result.trace.dataSource === "learner-feedback-sparse") {
387	    lines.push(
