405	  lines.push("");
406	  for (const benchmark of result.topicBenchmarks) {
407	    lines.push(`### ${benchmark.topic.title}`);
408	    lines.push(`- Dominant strength: ${benchmark.dominantStrength}`);
409	    lines.push(`- Dominant weakness: ${benchmark.dominantWeakness}`);
410	    lines.push("- Top learners:");
411	    for (const learner of benchmark.topLearners) {
412	      lines.push(
413	        `  - ${learner.learner.id}: ${(learner.score * 100).toFixed(1)} because ${(learner.explanation || ["unknown"]).join("; ")}`
414	      );
415	    }
416	    lines.push("- Struggling learners:");
417	    for (const learner of benchmark.strugglingLearners) {
418	      lines.push(
419	        `  - ${learner.learner.id}: ${(learner.score * 100).toFixed(1)} because ${(learner.explanation || ["unknown"]).join("; ")}`
420	      );
421	    }
422	    lines.push("");
423	  }
424	  lines.push("");
425	  return `${lines.join("\n")}\n`;
426	}
427	
428	export interface FeedbackSummary {
429	  confusionRate: number;
430	  satisfactionRate: number;
431	  sampleSize: number;
432	}
433	
434	export function applyFeedbackBias(
435	  feedback: FeedbackSummary
436	): SimulationWeights {
437	  if (feedback.sampleSize < 5) return { ...DEFAULT_WEIGHTS };
438	
439	  const weights = { ...DEFAULT_WEIGHTS };
440	  weights.confusion = clamp(weights.confusion + feedback.confusionRate * 0.08);
441	  weights.engagement = clamp(weights.engagement + feedback.satisfactionRate * 0.04);
442	
443	  const positiveSum = weights.masteryGain + weights.retention + weights.engagement + weights.transfer;
444	  const targetPositive = 1 - weights.confusion;
445	  const scale = targetPositive / positiveSum;
446	  weights.masteryGain *= scale;
447	  weights.retention *= scale;
448	  weights.engagement *= scale;
449	  weights.transfer *= scale;
450	
451	  return clampWeights(weights);
452	}
