187	function textFromMessage(message: AgentMessage): string {
188		const content = (message as any).content;
189		if (typeof content === "string") return content;
190		if (!Array.isArray(content)) return "";
191		return content
192			.filter((part) => part?.type === "text" && typeof part.text === "string")
193			.map((part) => part.text)
194			.join("\n");
195	}
