201			name: model?.name ?? model?.id ?? "Unlabeled model",
202			api: "api" in (model ?? {}) ? (model as SharedModelInfo).api : undefined,
203			baseUrl: "baseUrl" in (model ?? {}) ? (model as SharedModelInfo).baseUrl : undefined,
204		};
205	}
