207	async function loadBenchmarkSamples(): Promise<SessionSample[]> {
208		await getInitPromise();
209		const localMetadata = await sessions.getAllMetadata();
210		const localSessions = await Promise.all(
211			localMetadata.map(async (metadata) => {
212				const data = await sessions.loadSession(metadata.id) as SessionData | null;
213				if (!data) return null;
214				return {
215					id: data.id,
216					title: data.title,
217					source: "local" as const,
218					createdAt: data.createdAt,
219					model: serializeModel(data.model),
220					messages: data.messages,
221				};
222			}),
223		);
224		const shared: SessionSample[] = listCachedSharedSessions().map((session) => ({
225			id: session.id,
226			title: session.title,
227			source: "shared" as const,
228			createdAt: session.sharedAt,
229			model: session.model,
230			messages: session.messages,
231		}));
232		return [
233			...shared,
234			...localSessions.filter((session): session is NonNullable<typeof session> => Boolean(session)),
235		];
236	}
