244	function modelKey(model: SharedModelInfo) {
245		return `${model.provider}:${model.id}`;
246	}
247	
248	function clamp01(value: number) {
249		return Math.max(0, Math.min(1, value));
250	}
251	
252	function words(text: string) {
253		return text.trim().split(/\s+/).filter(Boolean).length;
254	}
255	
256	function hasAny(text: string, patterns: RegExp[]) {
257		return patterns.some((pattern) => pattern.test(text));
258	}
259	
260	function classifyReplayStage(text: string, signal: FeedbackSignal): ReplayStage {
261		const lowered = text.toLowerCase();
262		if (signal === "confused") return "confusion-recovery";
263		if (signal === "thumbs-down" || hasAny(lowered, [/\bwrong\b/, /\bincorrect\b/, /\bnot true\b/, /\bthat's not\b/])) return "correction";
264		if (hasAny(lowered, [/\bapply\b/, /\btransfer\b/, /\bnew example\b/, /\bscenario\b/, /\bquiz\b/, /\btest me\b/])) return "transfer";
265		if (hasAny(lowered, [/\bremember\b/, /\breview\b/, /\bdue\b/, /\bagain\b/, /\bretention\b/])) return "retention";
266		return "diagnosis";
267	}
268	
269	function scoreAssistantResponse(caseStage: ReplayStage, learnerText: string, assistantText: string, outcomeScore: number): ProsperVector {
270		const response = assistantText.toLowerCase();
271		const learner = learnerText.toLowerCase();
272		const lengthScore = clamp01(words(assistantText) / 120);
273		const checksUnderstanding = hasAny(response, [/\bdoes that make sense\b/, /\btry\b/, /\bwhat would\b/, /\bcan you\b/, /\btell me\b/, /\bcheck\b/]) ? 1 : 0.35;
274		const concrete = hasAny(response, [/\bexample\b/, /\bfor instance\b/, /\bbecause\b/, /\bstep\b/, /\bfirst\b/, /\btherefore\b/]) ? 1 : 0.45;
275		const acknowledgesState = caseStage === "confusion-recovery"
276			? hasAny(response, [/\bconfus/, /\bstuck\b/, /\bslow\b/, /\blet's unpack\b/, /\bstart over\b/]) ? 1 : 0.35
277			: caseStage === "correction"
278				? hasAny(response, [/\byou're right\b/, /\bcorrection\b/, /\bfix\b/, /\bmistake\b/, /\bmore precise\b/]) ? 1 : 0.35
279				: hasAny(response, [/\byou\b/, /\byour\b/, /\bfrom what\b/, /\blooks like\b/]) ? 0.85 : 0.45;
280		const transferCue = hasAny(response, [/\bapply\b/, /\bnew case\b/, /\banother example\b/, /\bpractice\b/, /\bquiz\b/, /\brecall\b/]) ? 1 : 0.35;
281		const learnerSpecificity = learner.length > 0 && hasAny(response, learner.split(/\W+/).filter((part) => part.length > 5).slice(0, 8).map((part) => new RegExp(`\\b${part.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\b`, "i"))) ? 1 : 0.55;
282	
283		return {
284			performance: outcomeScore,
285			robustness: clamp01((concrete + checksUnderstanding + lengthScore) / 3),
286			outcomeLift: clamp01(outcomeScore * 0.75 + (caseStage === "confusion-recovery" || caseStage === "correction" ? acknowledgesState * 0.25 : transferCue * 0.15)),
287			sparseCaution: 0,
288			personalization: clamp01((acknowledgesState + learnerSpecificity) / 2),
289			evidenceQuality: clamp01((concrete + lengthScore) / 2),
290			retentionTransfer: caseStage === "transfer" || caseStage === "retention" ? transferCue : clamp01(transferCue * 0.65 + checksUnderstanding * 0.35),
291		};
292	}
293	
294	function prosperMean(values: ProsperVector[]): ProsperVector {
295		if (values.length === 0) {
296			return {
297				performance: 0,
298				robustness: 0,
299				outcomeLift: 0,
300				sparseCaution: 0,
301				personalization: 0,
302				evidenceQuality: 0,
303				retentionTransfer: 0,
304			};
305		}
306		return values.reduce<ProsperVector>((acc, value) => ({
307			performance: acc.performance + value.performance / values.length,
308			robustness: acc.robustness + value.robustness / values.length,
309			outcomeLift: acc.outcomeLift + value.outcomeLift / values.length,
310			sparseCaution: acc.sparseCaution + value.sparseCaution / values.length,
311			personalization: acc.personalization + value.personalization / values.length,
312			evidenceQuality: acc.evidenceQuality + value.evidenceQuality / values.length,
313			retentionTransfer: acc.retentionTransfer + value.retentionTransfer / values.length,
314		}), {
315			performance: 0,
316			robustness: 0,
317			outcomeLift: 0,
318			sparseCaution: 0,
319			personalization: 0,
320			evidenceQuality: 0,
321			retentionTransfer: 0,
322		});
323	}
324	
325	function prosperTotal(vector: ProsperVector) {
326		return (
327			vector.performance * 0.2 +
328			vector.robustness * 0.14 +
329			vector.outcomeLift * 0.18 +
330			vector.sparseCaution * 0.14 +
331			vector.personalization * 0.12 +
332			vector.evidenceQuality * 0.1 +
333			vector.retentionTransfer * 0.12
334		) * 100;
335	}
