337	function readinessForSignals(signals: number): ReadinessBand {
338		if (signals >= READINESS_THRESHOLDS.stable) return "stable";
339		if (signals >= READINESS_THRESHOLDS.rankable) return "rankable";
340		if (signals >= READINESS_THRESHOLDS.provisional) return "provisional";
341		if (signals >= READINESS_THRESHOLDS.sparse) return "sparse";
342		return "waiting";
343	}
