345	function extractReplayCases(sample: SessionSample, model: SharedModelInfo): ReplayCase[] {
346		const key = modelKey(model);
347		const cases: ReplayCase[] = [];
348		for (let index = 0; index < sample.messages.length; index += 1) {
349			const message = sample.messages[index];
350			const role = (message as any).role;
351			if (role !== "user" && role !== "user-with-attachments") continue;
352			const learnerText = textFromMessage(message);
353			const inferred = inferBrowserLearnerTurnSignal(learnerText, sample.title);
354			if (!inferred) continue;
355			const beforeAssistantText = [...sample.messages.slice(0, index)].reverse().find((candidate) => (candidate as any).role === "assistant");
356			const afterAssistantText = sample.messages.slice(index + 1).find((candidate) => (candidate as any).role === "assistant");
357			const stage = classifyReplayStage(learnerText, inferred.signal);
358			const outcomeScore = feedbackToOutcomeScore(inferred.signal);
359			const responseText = textFromMessage(afterAssistantText ?? beforeAssistantText ?? message);
360			const prosper = scoreAssistantResponse(stage, learnerText, responseText, outcomeScore);
361			cases.push({
362				id: `${sample.id}:${index}`,
363				sessionId: sample.id,
364				sessionTitle: sample.title,
365				source: sample.source,
366				modelKey: key,
367				stage,
368				signal: inferred.signal,
369				learnerText,
370				beforeAssistantText: textFromMessage(beforeAssistantText ?? message).slice(0, 420),
371				afterAssistantText: textFromMessage(afterAssistantText ?? message).slice(0, 420),
372				outcomeScore,
373				prosper,
374			});
375		}
376		return cases;
377	}
