379	function aggregateSamples(samples: SessionSample[], source: BenchmarkSource): ModelAggregate[] {
380		const filtered = source === "all" ? samples : samples.filter((sample) => sample.source === source);
381		const aggregates = new Map<string, ModelAggregate>();
382	
383		for (const sample of filtered) {
384			const model = serializeModel(sample.model);
385			const key = modelKey(model);
386			const existing = aggregates.get(key) ?? {
387				key,
388				name: model.name ?? model.id,
389				provider: model.provider,
390				score: 0,
391				prosperScore: 0,
392				prosper: prosperMean([]),
393				confidence: 0,
394				sessions: 0,
395				sharedSessions: 0,
396				localSessions: 0,
397				signals: 0,
398				turns: 0,
399				tokens: 0,
400				cost: 0,
401				latestAt: sample.createdAt,
402				readiness: "waiting" as const,
403				outcomes: [],
404				replayCases: [],
405			};
406			existing.sessions += 1;
407			existing.sharedSessions += sample.source === "shared" ? 1 : 0;
408			existing.localSessions += sample.source === "local" ? 1 : 0;
409			existing.latestAt = existing.latestAt.localeCompare(sample.createdAt) > 0 ? existing.latestAt : sample.createdAt;
410			const usage = sessionUsage(sample.messages);
411			existing.tokens += usage.totalTokens || usage.input + usage.output;
412			existing.cost += usage.cost.total;
413	
414			existing.turns += sample.messages.filter((message) => {
415				const role = (message as any).role;
416				return role === "user" || role === "user-with-attachments";
417			}).length;
418			const replayCases = extractReplayCases(sample, model);
419			existing.replayCases.push(...replayCases);
420			existing.outcomes.push(...replayCases.map((replayCase) => ({
421				signal: replayCase.signal,
422				score: replayCase.outcomeScore,
423				source: "inferred-turn" as const,
424				stage: replayCase.stage,
425				prosper: replayCase.prosper,
426			})));
427			aggregates.set(key, existing);
428		}
429	
430		return [...aggregates.values()]
431			.map((aggregate) => {
432				const mean = aggregate.outcomes.length
433					? aggregate.outcomes.reduce((sum, outcome) => sum + outcome.score, 0) / aggregate.outcomes.length
434					: 0;
435				const confidence = Math.min(1, aggregate.outcomes.length / 20);
436				const readiness = readinessForSignals(aggregate.outcomes.length);
437				const prosperBase = prosperMean(aggregate.outcomes.map((outcome) => outcome.prosper));
438				const sparseCaution = readiness === "waiting"
439					? 0
440					: readiness === "sparse"
441						? 0.45
442						: readiness === "provisional"
443							? 0.7
444							: readiness === "rankable"
445								? 0.9
446								: 1;
447				const prosper = { ...prosperBase, sparseCaution };
448				return {
449					...aggregate,
450					score: mean * 100,
451					prosper,
452					prosperScore: prosperTotal(prosper),
453					confidence,
454					signals: aggregate.outcomes.length,
455					readiness,
456				};
457			})
458			.sort((a, b) => {
459				const adjustedA = a.prosperScore * (0.72 + a.confidence * 0.28);
460				const adjustedB = b.prosperScore * (0.72 + b.confidence * 0.28);
461				return adjustedB - adjustedA || b.signals - a.signals || b.sessions - a.sessions;
462			});
463	}
