872							{replayCases.slice(0, 8).map((replayCase) => (
873								<div key={replayCase.id} className={styles.replayCase}>
874									<div className={styles.replayLeft}>
875										<StagePill stage={replayCase.stage} />
876										<span className={styles.pill}>{replayCase.signal}</span>
877									</div>
878									<div className={styles.min0}>
879										<div className={cx(styles.truncate, css({ fontSize: "0.875rem", fontWeight: "500" }))}>{replayCase.sessionTitle}</div>
880										<p className={styles.lineClamp2}>
881											{replayCase.learnerText}
882										</p>
883									</div>
884									<div className={styles.twoColNums}>
885										<div className={styles.statBox}>
886											<div className={styles.mutedIcon}>Outcome</div>
887											<div className={styles.mt1FontMedium}>{Math.round(replayCase.outcomeScore * 100)}%</div>
888										</div>
889										<div className={styles.statBox}>
890											<div className={styles.mutedIcon}>PROSPER</div>
891											<div className={styles.mt1FontMedium}>{prosperTotal(replayCase.prosper).toFixed(1)}</div>
892										</div>
893									</div>
894								</div>
895							))}
896							{replayCases.length === 0 && <div className={styles.empty}>No replay cases yet</div>}
897						</div>
898					</section>
899	
900					<MethodologyExplainer />
901				</main>
902			</div>
903		);
904	}
905	
906	export function KeatingBench() {
907		useSeo({
908			title: "KeatingBench | Model Learning Leaderboard",
909			description: "Rank teaching models by shared learner-session outcomes and feedback signals.",
910			canonical: "https://keating.help/bench",
911		});
