28	export interface OptimizePolicyOptions {
29	  nTrials?: number;
30	  objectives?: string[]; // e.g. ["voice", "diagnosis", "engagement", "transfer", "cost"]
31	  focusTopic?: string;
32	  seed?: number;
33	}
34	
35	/**
36	 * Optimizes the TeacherPolicy using GEPA multi-objective tuning.
37	 */
38	export async function optimizePolicy(
39	  cwd: string,
40	  basePolicy: TeacherPolicy,
41	  options: OptimizePolicyOptions = {}
42	): Promise<EvolutionRun> {
43	  const { nTrials = 24, objectives = ["score", "transfer", "engagement"], focusTopic, seed = 20260401 } = options;
44	
45	  console.log(`Starting GEPA Policy Optimization (${nTrials} trials, objectives: ${objectives.join(", ")})`);
46	
47	  const objective: KeatingObjective = async (trial) => {
48	    const policy = trialToPolicy(trial, `gepa-candidate-${trial.params.iteration ?? 0}`);
49	    const weights = trialToWeights(trial);
50	    const benchmark = await runBenchmarkSuite(cwd, policy, focusTopic, seed, 3, weights);
51	    
52	    const result: Record<string, number> = {};
53	    for (const obj of objectives) {
54	      if (obj === "score") result[obj] = benchmark.overallScore / 100;
55	      else if (obj === "transfer") result[obj] = mean(benchmark.topicBenchmarks.map(b => b.meanTransfer));
56	      else if (obj === "engagement") result[obj] = mean(benchmark.topicBenchmarks.map(b => b.meanEngagement));
57	      else if (obj === "retention") result[obj] = mean(benchmark.topicBenchmarks.map(b => b.meanRetention));
58	      else if (obj === "confusion") result[obj] = 1 - mean(benchmark.topicBenchmarks.map(b => b.meanConfusion));
59	    }
60	    return result;
61	  };
62	
63	  try {
64	    const study = await optimize(objective, {
65	      nTrials,
66	      direction: "maximize",
67	      seed
68	    });
69	
70	    const bestPolicy = trialToPolicy(
71	      new PolicyTrial(study.bestParams),
72	      `gepa-best-${Date.now().toString(36)}`
73	    );
74	
75	    const archiveContent = await readFile(join(stateDir(cwd), "policy-archive.json"), "utf8").catch(() => "[]");
76	    const archive = JSON.parse(archiveContent);
77	
78	    const baseline = await runBenchmarkSuite(cwd, basePolicy, focusTopic, seed);
79	    const best = await runBenchmarkSuite(cwd, bestPolicy, focusTopic, seed);
80	    const paretoBenchmarks = await Promise.all(
81	      study.paretoFront.map((p, i) => {
82	        const policy = trialToPolicy(new PolicyTrial(p.params), `gepa-pareto-${i}`);
83	        const weights = trialToWeights(new PolicyTrial(p.params));
84	        return runBenchmarkSuite(cwd, policy, focusTopic, seed + i * 17, 3, weights);
85	      })
86	    );
87	
88	    const run: EvolutionRun = {
89	      baseline,
90	      best,
91	      acceptedCandidates: [], // Not using candidate-by-candidate acceptance here
92	      exploredCandidates: study.paretoFront.map((p, i) => ({
93	        policy: paretoBenchmarks[i].policy,
94	        benchmark: paretoBenchmarks[i],
95	        parentName: basePolicy.name,
96	        iteration: i,
97	        novelty: 1.0,
98	        accepted: true,
99	        parameterDelta: [],
100	        decision: { improves: true, safe: true, novelEnough: true, scoreDelta: 0, weakestTopicDelta: 0, reasons: [] }
101	      })),
102	      archive: {
103	        currentPolicy: bestPolicy,
104	        bestScore: best.overallScore,
105	        candidates: study.paretoFront.map(p => ({
106	          policy: trialToPolicy(new PolicyTrial(p.params), "gepa"),
107	          score: mean(Object.values(p.scores)) * 100,
108	          novelty: 1.0,
109	          accepted: true,
110	          iteration: 0
111	        }))
112	      },
113	      metadata: { optimizerUsed: "gepa" }
114	    };
115	
116	    await writeFile(gepaResultPath(cwd), JSON.stringify(study, null, 2), "utf8");
117	
118	    return run;
