        policy: entry.policy,
        score: entry.benchmark.overallScore,
        novelty: entry.novelty,
        accepted: entry.accepted,
        iteration: entry.iteration
      }))
    ]
  };

  await saveArchive(archivePath, nextArchive);
  return {
    baseline,
    best,
    acceptedCandidates,
    exploredCandidates,
    archive: nextArchive
  };
}

